-- Ampliacion persistente: ejecutar despues de 05, exclusivamente en la copia aislada.
-- SQL explicito: sin cursores, SQL dinamico ni funciones nuevas. Correos ficticios no entregables.
:ON ERROR EXIT
USE [NexoSalud_InstalacionValidacion];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name='Cohorte500Lead')
BEGIN
 PRINT 'Cohorte ya instalada; no insertar duplicados.';
END
ELSE
BEGIN TRY
 IF DB_NAME()<>'NexoSalud_InstalacionValidacion' OR (SELECT COUNT(*) FROM dbo.Personas)<>6
 OR (SELECT COUNT(*) FROM dbo.Personas WHERE email IN('caso1@example.invalid','caso2@example.invalid','caso3@example.invalid','caso4@example.invalid','caso5@example.invalid','caso6@example.invalid'))<>6
 THROW 55310,'Se requieren exactamente los seis casos de 05 en el destino aislado.',1;
 BEGIN TRAN;
 DECLARE @buyer int=(SELECT id_etapa FROM dbo.Etapas WHERE nombre='BUYER'),@canal int=(SELECT MIN(id_canal) FROM dbo.Canales WHERE nombre='Formulario Web');
 DECLARE @persona int,@captacion int,@sol int,@raiz int,@version int,@op int,@pref int,@slot int,@precio decimal(10,2),@t datetime2,@decision datetime2;
 DECLARE @sv1 int,@sv2 int,@sv3 int,@sd1 int,@sd2 int,@sd3 int,@pf1 int,@pf2 int,@pf3 int,@promo int,@me int,@mo int,@mi int,@ma int;
 INSERT dbo.Servicios(nombre,descripcion) VALUES('Limpieza DEMO','Profilaxis ficticia de presentacion'); SET @sv1=SCOPE_IDENTITY();
 INSERT dbo.Servicios(nombre,descripcion) VALUES('Ortodoncia DEMO','Evaluacion inicial ficticia, sin diagnostico'); SET @sv2=SCOPE_IDENTITY();
 INSERT dbo.Servicios(nombre,descripcion) VALUES('Restauracion DEMO','Consulta ficticia de presentacion'); SET @sv3=SCOPE_IDENTITY();
 INSERT dbo.Tarifas(id_servicio,precio) VALUES(@sv1,100),(@sv2,200),(@sv3,150);
 INSERT dbo.Sedes(nombre,direccion,zona) VALUES('DEMO Centro','Direccion ficticia 100','Centro'); SET @sd1=SCOPE_IDENTITY();
 INSERT dbo.Sedes(nombre,direccion,zona) VALUES('DEMO Norte','Direccion ficticia 200','Norte'); SET @sd2=SCOPE_IDENTITY();
 INSERT dbo.Sedes(nombre,direccion,zona) VALUES('DEMO Sur','Direccion ficticia 300','Sur'); SET @sd3=SCOPE_IDENTITY();
 INSERT dbo.Profesionales(nombres,apellidos,especialidad) VALUES('Valeria','DEMO','Odontologia general'); SET @pf1=SCOPE_IDENTITY();
 INSERT dbo.Profesionales(nombres,apellidos,especialidad) VALUES('Diego','DEMO','Ortodoncia'); SET @pf2=SCOPE_IDENTITY();
 INSERT dbo.Profesionales(nombres,apellidos,especialidad) VALUES('Lucia','DEMO','Restauraciones'); SET @pf3=SCOPE_IDENTITY();
 INSERT dbo.ProfesionalServicio VALUES(@pf1,@sv1),(@pf2,@sv2),(@pf3,@sv3);
 INSERT dbo.PromocionesLead(nombre,tipo_promocion) VALUES('DEMO descuento diez por ciento','Descuento 10%'); SET @promo=SCOPE_IDENTITY();
 INSERT dbo.MotivosRechazoLead(codigo,ambito,categoria,motivo) VALUES('DEMO-P-E','PROPUESTA','ECONOMICO','Presupuesto insuficiente expresado'); SET @me=SCOPE_IDENTITY();
 INSERT dbo.MotivosRechazoLead(codigo,ambito,categoria,motivo) VALUES('DEMO-P-O','PROPUESTA','OTROS','Decide postergar voluntariamente'); SET @mo=SCOPE_IDENTITY();
 INSERT dbo.MotivosRechazoLead(codigo,ambito,categoria,motivo) VALUES('DEMO-A-I','ALTERNATIVA','INCOMPATIBILIDAD','No puede asistir en el turno ofrecido'); SET @mi=SCOPE_IDENTITY();
 INSERT dbo.MotivosRechazoLead(codigo,ambito,categoria,motivo) VALUES('DEMO-A-O','ALTERNATIVA','OTROS','Declina opcion al postergar tratamiento'); SET @ma=SCOPE_IDENTITY();
 DECLARE @servicio int,@sede int,@prof int;
