UPDATE dbo.Opciones SET estado_respuesta='Aceptada',fecha_respuesta=SYSDATETIME(),seleccionada=1 WHERE id_opcion=@op;
UPDATE dbo.Solicitudes SET resultado_comercial_lead='ACEPTADA',valor_acordado_lead=@precio,id_propuesta_aceptada_lead=@version,fecha_decision_comercial_lead=SYSDATETIME() WHERE id_solicitud=@sol;
