 OR (SELECT SUM(alternativa_rechazada) FROM dbo.fn_Lead_Alternativas_Corte(@cut))<>160
 OR (SELECT SUM(alternativa_rechazada_incompatibilidad) FROM dbo.fn_Lead_Alternativas_Corte(@cut))<>40
 THROW 55312,'No concilian las ocho medidas con el diseno de casos.',1;
 IF EXISTS(SELECT 1 FROM dbo.Reservas) OR EXISTS(SELECT 1 FROM dbo.Pagos) OR EXISTS(SELECT 1 FROM dbo.Atenciones) OR EXISTS(SELECT 1 FROM dbo.Seguimientos)
