 EXEC sys.sp_addextendedproperty @name='Cohorte500Lead',@value='500 personas; 403 solicitudes; M=80,160,120,120,80,80,160,40';
 COMMIT;
 SELECT 'OK' resultado,500 personas,403 solicitudes,80 M1,160 M2,120 M3,120 M4,80 M5,80 M6,160 M7,40 M8;
